INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um homem de 45 anos, motorista de carga pesada, apresenta-se ao ambulatório com queixa de dor lombar intensa que se irradia para a face lateral da perna esquerda e dorso do pé. Durante o exame físico, observa-se diminuição da força na dorsiflexão do hálux e sensibilidade alterada no primeiro espaço interdigital. Ao revisar a anatomia da coluna vertebral, o médico identifica que a hérnia de disco provável está comprimindo uma raiz nervosa que emerge abaixo da vértebra correspondente. Considerando as características anatômicas das vértebras lombares e a emergência das raízes nervosas, assinale a alternativa que descreve corretamente a relação anatômica envolvida.","options":{"a":"A raiz de L5 emerge pelo forame intervertebral entre L5 e S1, sendo tipicamente comprimida por uma hérnia discal nesse nível.","b":"As vértebras lombares possuem forames transversários que protegem a passagem das raízes nervosas antes de sua saída pelo forame intervertebral.","c":"O processo espinhoso das vértebras lombares é delgado e inclinado inferiormente, dificultando o acesso cirúrgico posterior ao canal vertebral.","d":"O ligamento amarelo conecta os processos transversos de vértebras adjacentes, servindo como limite anterior do forame intervertebral.","e":"O canal vertebral no nível lombar é circular e estreito, o que predispõe à síndrome da cauda equina em casos de protusões centrais mínimas."},"answer":"a","rationale":"A questão aborda a anatomia aplicada da coluna lombar. No nível lombar, as raízes nervosas emergem abaixo da vértebra de mesma numeração. A sintomatologia descrita (fraqueza na dorsiflexão do hálux e parestesia no dorso do pé) é clássica de compressão da raiz de L5. A raiz de L5 sai pelo forame entre L5 e S1. Portanto, a alternativa A reflete corretamente a anatomia de emergência nervosa e a correlação clínica habitual das hérnias discais posterolaterais.","option_rationales":{"a":"Correta. A emergência das raízes lombares ocorre logo abaixo do pedículo da vértebra correspondente.","b":"Errada. Forames transversários são características exclusivas das vértebras cervicais (passagem da artéria vertebral).","c":"Errada. O processo espinhoso lombar é quadrilátero, robusto e horizontalizado.","d":"Errada. O ligamento amarelo conecta as lâminas das vértebras, não os processos transversos; o limite anterior do forame é o disco e o corpo vertebral.","e":"Errada. O canal vertebral lombar tende a ser triangular; protusões \"mínimas\" raramente causam síndrome da cauda equina, que exige compressão volumosa."},"difficulty":"Média","tags":["Anatomia","Coluna Vertebral","Neuroanatomia Aplicada"]}', '4bac0f35abc0baa98369536c9c9914fd', 0, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Durante uma cirurgia de correção de hérnia inguinal por via aberta (técnica de Lichtenstein), o cirurgião precisa identificar as estruturas que compõem o canal inguinal para posicionar a tela adequadamente. Ao dissecar a região, identifica-se uma camada aponeurótica que forma a parede anterior do canal em quase toda a sua extensão e cujo bordo inferior se enrola para formar o ligamento inguinal. Essa estrutura anatômica é derivada de qual dos seguintes músculos ou aponeuroses?","options":{"a":"Músculo transverso do abdome.","b":"Aponeurose do músculo oblíquo externo.","c":"Fáscia transversalis.","d":"Músculo oblíquo interno.","e":"Músculo reto abdominal."},"answer":"b","rationale":"O canal inguinal é uma passagem oblíqua através da parede abdominal. A parede anterior é formada primordialmente pela aponeurose do músculo oblíquo externo do abdome. O ligamento inguinal (de Poupart) é, de fato, o bordo inferior espessado e fletido dessa aponeurose, estendendo-se da espinha ilíaca anterossuperior ao tubérculo púbico. O conhecimento dessas camadas é fundamental para a técnica cirúrgica de reparo de hérnias.","option_rationales":{"a":"Errada. O transverso do abdome forma a parede posterior (via tendão conjunto) e o teto do canal, mas não a parede anterior.","b":"Correta. A aponeurose do oblíquo externo forma a parede anterior e o ligamento inguinal.","c":"Errada. A fáscia transversalis forma a parede posterior do canal inguinal.","d":"Errada. O oblíquo interno contribui para o teto do canal e, em conjunto com o transverso, forma o foice inguinal (tendão conjunto).","e":"Errada. O músculo reto abdominal situa-se medialmente ao canal inguinal e não compõe suas paredes diretas."},"difficulty":"Média","tags":["Anatomia","Parede Abdominal","Canal Inguinal"]}', 'dbb6249eb49d7634c129d95aec94c379', 1, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente vítima de trauma torácico fechado apresenta fratura de múltiplas costelas, resultando em um quadro de tórax instável. Durante a avaliação radiológica, nota-se que a fratura ocorreu na região mais frágil da costela, onde o osso apresenta sua maior curvatura e o sulco costal é mais evidente. Além disso, o médico deve estar atento ao feixe vasculonervoso intercostal. Com base na anatomia das costelas típicas, assinale a alternativa que descreve corretamente a localização do feixe vasculonervoso intercostal.","options":{"a":"O feixe localiza-se na borda superior da costela, protegido pelo músculo intercostal externo.","b":"O feixe localiza-se na borda inferior da costela, no sulco da costela, entre os músculos intercostal interno e íntimo.","c":"O feixe localiza-se superficialmente ao músculo intercostal externo, logo abaixo da fáscia peitoral.","d":"O nervo intercostal situa-se superiormente à artéria e à veia dentro do sulco costal.","e":"A veia intercostal é a estrutura mais inferior do feixe, sendo a primeira a ser lesada em punções inadvertidas na borda inferior."},"answer":"b","rationale":"As costelas típicas (3ª a 9ª) possuem um sulco na face interna de sua borda inferior. O feixe vasculonervoso intercostal (Veia, Artéria, Nervo - mnemônico VAN) percorre esse sulco. Anatômica e cirurgicamente, o feixe situa-se no plano entre as camadas média (intercostal interno) e profunda (intercostal íntimo) dos músculos intercostais. Por isso, orienta-se realizar punções torácicas na borda SUPERIOR da costela inferior ao espaço, para evitar lesão do feixe.","option_rationales":{"a":"Errada. O feixe situa-se na borda inferior, não na superior.","b":"Correta. Esta é a descrição clássica da topografia do feixe VAN intercostal.","c":"Errada. O feixe é profundo aos músculos intercostais externo e interno.","d":"Errada. A ordem de superior para inferior é Veia, Artéria e Nervo (VAN); o nervo é o mais inferior.","e":"Errada. O nervo é a estrutura mais inferior do feixe, não a veia."},"difficulty":"Média","tags":["Anatomia","Tórax","Osteologia"]}', '9b9a82fa978dd4f27c776cb26283df9c', 2, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O diafragma é o principal músculo da respiração e separa as cavidades torácica e abdominal. Ele possui hiatos que permitem a passagem de estruturas fundamentais entre essas cavidades. Um paciente com esofagite de refluxo grave apresenta hérnia de hiato ao exame endoscópico. Anatômica e funcionalmente, o hiato esofágico é formado predominantemente por fibras de qual estrutura?","options":{"a":"Pilar direito do diafragma.","b":"Pilar esquerdo do diafragma.","c":"Centro tendíneo do diafragma.","d":"Ligamento arqueado mediano.","e":"Ligamento arqueado lateral."},"answer":"a","rationale":"O diafragma possui três grandes aberturas: o forame da veia cava (no centro tendíneo, nível T8), o hiato esofágico (nível T10) e o hiato aórtico (nível T12). O hiato esofágico é formado por uma fenda muscular nas fibras do pilar direito do diafragma, que se cruzam para formar uma espécie de esfíncter extrínseco ao redor do esôfago. Fraquezas nessas fibras contribuem para o desenvolvimento de hérnias de hiato.","option_rationales":{"a":"Correta. O pilar direito circunda o esôfago na maioria dos indivíduos.","b":"Errada. O pilar esquerdo é menor e raramente contribui significativamente para a formação do hiato esofágico.","c":"Errada. O centro tendíneo abriga o forame da veia cava, não o hiato esofágico.","d":"Errada. O ligamento arqueado mediano forma o arco anterior do hiato aórtico.","e":"Errada. O ligamento arqueado lateral é um espessamento da fáscia do músculo quadrado lombar e não forma hiatos viscerais."},"difficulty":"Média","tags":["Anatomia","Diafragma","Sistema Digestório"]}', '15915cc748c81f9d62c303590d4dcd16', 3, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Durante um exame físico de rotina, um médico solicita que o paciente realize uma inspiração profunda forçada. Ele observa a contração dos músculos acessórios da respiração. Entre os músculos citados abaixo, qual deles atua como um músculo inspiratório acessório ao elevar as primeiras e segundas costelas?","options":{"a":"Músculos escalenos.","b":"Músculo reto abdominal.","c":"Músculo transverso do tórax.","d":"Músculos intercostais internos (parte interóssea).","e":"Músculo oblíquo externo."},"answer":"a","rationale":"Na inspiração forçada ou em situações de insuficiência respiratória, músculos acessórios são recrutados para aumentar o volume da caixa torácica. Os músculos escalenos (anterior, médio e posterior), localizados no pescoço, fixam-se no processo transverso das vértebras cervicais e inserem-se na 1ª e 2ª costelas. Sua contração eleva essas costelas, auxiliando na expansão do diâmetro superior do tórax.","option_rationales":{"a":"Correta. Os escalenos elevam as costelas superiores.","b":"Errada. O reto abdominal é um potente músculo expiratório acessório (comprime as vísceras e abaixa as costelas).","c":"Errada. O transverso do tórax auxilia no abaixamento das cartilagens costais (expiração).","d":"Errada. A parte interóssea dos intercostais internos atua na expiração forçada; apenas a parte intercondral auxilia na inspiração.","e":"Errada. O oblíquo externo é um músculo expiratório acessório."},"difficulty":"Fácil","tags":["Anatomia","Músculos","Sistema Respiratório"]}', 'a56fe12d3fc01d76f5ff360331bd1cc0', 4, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A articulação atlantoaxial é responsável por grande parte da amplitude de movimento de rotação da cabeça. Ela é composta por articulações sinoviais entre o atlas (C1) e o áxis (C2). O dente do áxis é a estrutura central desse movimento, sendo mantido em posição contra o arco anterior do atlas por um ligamento crucial para a estabilidade da coluna cervical superior. Em casos de artrite reumatoide grave, esse ligamento pode sofrer erosão, levando à subluxação atlantoaxial perigosa. Qual é esse ligamento?","options":{"a":"Ligamento alar.","b":"Ligamento transverso do atlas.","c":"Ligamento amarelo.","d":"Ligamento nucal.","e":"Ligamento longitudinal anterior."},"answer":"b","rationale":"O ligamento transverso do atlas estende-se entre os tubérculos nas massas laterais de C1, passando posteriormente ao dente do áxis. Ele forma a parede posterior da articulação trocoide atlantoaxial mediana. Sua integridade impede que o dente se desloque para trás e comprima a medula espinal. Ligamentos alares limitam a rotação, mas o transverso é o principal estabilizador \"em pivô\".","option_rationales":{"a":"Errada. Os ligamentos alares unem o dente aos côndilos occipitais e limitam a rotação lateral excessiva.","b":"Correta. O ligamento transverso é o pilar da estabilidade atlantoaxial mediana.","c":"Errada. O ligamento amarelo está presente entre as lâminas de todas as vértebras abaixo de C1.","d":"Errada. O ligamento nucal é um septo fibroso posterior que se estende da protuberância occipital externa aos processos espinhosos cervicais.","e":"Errada. O ligamento longitudinal anterior percorre a face anterior dos corpos vertebrais; ele não estabiliza o dente do áxis especificamente."},"difficulty":"Média","tags":["Anatomia","Artrologia","Coluna Vertebral"]}', '370717706e8a08eb63bb2e7d1a3e2f46', 5, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um estudante de medicina observa, durante a dissecação de um cadáver, uma estrutura fibrosa que corre verticalmente na linha média da parede abdominal anterior, estendendo-se do processo xifoide à sínfise púbica. Ele nota que essa estrutura é formada pela decussação das aponeuroses dos músculos oblíquo externo, oblíquo interno e transverso do abdome. Sabendo que essa região é um local comum para a realização de laparotomias por ser relativamente avascular, identifique a estrutura descrita.","options":{"a":"Linha semilunar.","b":"Fáscia de Scarpa.","c":"Linha alba.","d":"Bainha do músculo reto.","e":"Ligamento de Cooper."},"answer":"c","rationale":"A linha alba é o rafe fibroso central da parede abdominal anterior. Ela resulta do entrelaçamento das fibras aponeuróticas dos músculos largos do abdome de ambos os lados. Como contém poucos vasos sanguíneos e nervos significativos, é a via de escolha para a incisão mediana (laparotomia mediana), facilitando o acesso rápido e com sangramento mínimo à cavidade peritoneal.","option_rationales":{"a":"Errada. A linha semilunar marca o limite lateral do músculo reto abdominal.","b":"Errada. A fáscia de Scarpa é uma camada profunda e membranosa da tela subcutânea abdominal.","c":"Correta. Descrição clássica da linha alba abdominal.","d":"Errada. A bainha do músculo reto é o invólucro aponeurótico do músculo reto, mas a estrutura central é a linha alba.","e":"Errada. O ligamento de Cooper (pectíneo) localiza-se na crista pectínea do púbis."},"difficulty":"Fácil","tags":["Anatomia","Parede Abdominal","Músculos"]}', '699cefcb4abe1a5ed2a0669c0ffb22a9', 6, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A parede torácica é suprida por artérias intercostais que se anastomosam para garantir a perfusão dos tecidos. A maioria das artérias intercostais posteriores origina-se diretamente da aorta torácica. No entanto, as duas primeiras artérias intercostais posteriores originam-se de um tronco comum. Identifique a origem correta das artérias intercostais posteriores do 1º e 2º espaços.","options":{"a":"Artéria mamária interna (torácica interna).","b":"Artéria intercostal suprema, ramo do tronco costocervical.","c":"Artéria subclávia, ramo direto.","d":"Artéria carótida comum.","e":"Artéria axilar, ramo torácico superior."},"answer":"b","rationale":"O suprimento arterial das paredes torácicas é distribuído entre artérias intercostais anteriores (ramos da torácica interna) e posteriores. As intercostais posteriores do 3º ao 11º espaço nascem da aorta. Já as dos dois primeiros espaços derivam da artéria intercostal suprema, que por sua vez é um ramo do tronco costocervical, um dos ramos da segunda porção da artéria subclávia. Esse detalhe é frequente em provas de anatomia vascular.","option_rationales":{"a":"Errada. A torácica interna dá origem às intercostais anteriores.","b":"Correta. A intercostal suprema supre os dois primeiros espaços posteriores.","c":"Errada. Não nascem diretamente da subclávia, mas via tronco costocervical.","d":"Errada. A carótida comum supre cabeça e pescoço.","e":"Errada. A torácica superior supre a parte superior da parede torácica, mas não as intercostais posteriores típicas."},"difficulty":"Difícil","tags":["Anatomia","Vascularização","Tórax"]}', '013e151d735353d9abfa6db9b811c217', 7, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente de 60 anos apresenta dificuldade progressiva para defecar e dor na região perineal. O exame físico revela uma hérnia que protrui através de uma fraqueza no assoalho pélvico. Anatomia básica: o assoalho pélvico (diafragma da pélvis) é formado primordialmente por um complexo muscular que sustenta as vísceras pélvicas. Qual é o principal músculo desse complexo?","options":{"a":"Músculo piriforme.","b":"Músculo levantador do ânus.","c":"Músculo obturador interno.","d":"Músculo psoas maior.","e":"Músculo glúteo máximo."},"answer":"b","rationale":"O diafragma da pélvis é a estrutura muscular que fecha a abertura inferior da pélvis. Ele é composto principalmente pelo músculo levantador do ânus (formado pelos músculos puborretal, pubococcígeo e iliococcígeo) e pelo músculo isquiococcígeo (coccígeo). O levantador do ânus é essencial para a continência fecal e urinária, além de sustentar o útero, bexiga e reto.","option_rationales":{"a":"Errada. O piriforme é um músculo da parede posterior da pélvis que atua no quadril.","b":"Correta. O levantador do ânus é o principal componente do assoalho pélvico.","c":"Errada. O obturador interno forma a parede lateral da pélvis menor.","d":"Errada. O psoas maior localiza-se na parede abdominal posterior.","e":"Errada. O glúteo máximo é um músculo extrínseco da região glútea."},"difficulty":"Média","tags":["Anatomia","Pélvis","Assoalho Pélvico"]}', 'b3946646d8ce6cc0d4667aabd042c1bd', 8, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Durante uma punção lombar (colheita de líquor), a agulha deve atravessar várias camadas de tecido antes de atingir o espaço subaracnóideo. Após atravessar a pele e o tecido subcutâneo na linha média entre os processos espinhosos de L3 e L4, qual é a sequência correta dos ligamentos perfurados pela agulha até chegar à dura-máter?","options":{"a":"Ligamento supraespinal → Ligamento infraespinal → Ligamento amarelo.","b":"Ligamento supraespinal → Ligamento interespinal → Ligamento amarelo.","c":"Ligamento interespinal → Ligamento supraespinal → Ligamento longitudinal posterior.","d":"Ligamento longitudinal anterior → Ligamento amarelo → Ligamento interespinal.","e":"Ligamento nucal → Ligamento interespinal → Ligamento amarelo."},"answer":"b","rationale":"Para realizar uma punção lombar mediana, a agulha percorre: Pele → Subcutâneo → Ligamento supraespinal (que conecta as pontas dos processos espinhosos) → Ligamento interespinal (entre os processos espinhosos) → Ligamento amarelo (entre as lâminas). Ao perfurar o ligamento amarelo, sente-se frequentemente uma \"perda de resistência\". Após o ligamento amarelo e o espaço epidural, a agulha perfura a dura-máter e a aracnóide para colher o líquor.","option_rationales":{"a":"Errada. \"Infraespinal\" não é a nomenclatura anatômica padrão para o ligamento interespinal.","b":"Correta. Sequência exata dos ligamentos de posterior para anterior na linha média.","c":"Errada. O supraespinal é mais superficial que o interespinal; o longitudinal posterior é anterior à medula.","d":"Errada. O longitudinal anterior é a estrutura mais anterior da coluna, não sendo perfurado na punção posterior.","e":"Errada. O ligamento nucal existe apenas na região cervical."},"difficulty":"Média","tags":["Anatomia","Coluna Vertebral","Prática Clínica"]}', '0e1d07a0028dc8a26eb11eccc4be0fcc', 9, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A anatomia da superfície do dorso permite a identificação de pontos de referência importantes. Ao palpar o processo espinhoso mais proeminente na base do pescoço quando o paciente flexiona a cabeça, o examinador identifica a vértebra tecnicamente chamada de \"vértebra proeminente\". Qual é a numeração correta dessa vértebra?","options":{"a":"C5.","b":"C6.","c":"C7.","d":"T1.","e":"T2."},"answer":"c","rationale":"A 7ª vértebra cervical (C7) possui um processo espinhoso longo, não bifurcado e muito proeminente, o que a torna um marco anatômico fundamental para a contagem das vértebras no exame físico do dorso. Embora o processo espinhoso de T1 também seja proeminente, o de C7 é o ponto de referência clássico descrito na anatomia sistemática como \"vértebra proeminens\".","option_rationales":{"a":"Errada. C5 não é proeminente ao toque superficial.","b":"Errada. C6 é identificada pelo tubérculo carótico, mas não pelo processo espinhoso no dorso.","c":"Correta. C7 é a definição técnica de vértebra proeminente.","d":"Errada. T1 é proeminente, mas situa-se logo abaixo da C7.","e":"Errada. T2 é oculta pela musculatura do trapézio superior."},"difficulty":"Fácil","tags":["Anatomia","Coluna Vertebral","Osteologia"]}', '2fff583fd1f616feebb9ded637c4c52c', 10, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A respiração paradoxal é um sinal clínico de grave insuficiência respiratória ou lesão traumática (como o tórax instável). Em recém-nascidos, devido à complacência da caixa torácica, a inspiração pode causar retrações intercostais. Do ponto de vista anatômico, o movimento de \"alça de balde\" (bucket handle), que aumenta o diâmetro lateral (transverso) do tórax durante a inspiração, é realizado predominantemente por quais costelas?","options":{"a":"1ª e 2ª costelas.","b":"3ª a 6ª costelas.","c":"7ª a 10ª costelas.","d":"11ª e 12ª costelas.","e":"Apenas as costelas flutuantes."},"answer":"c","rationale":"Existem dois movimentos clássicos das costelas na inspiração: o \"braço de bomba\" (pump handle), que eleva as extremidades anteriores das costelas superiores (2-6) aumentando o diâmetro anteroposterior; e a \"alça de balde\" (bucket handle), típico das costelas inferiores (7-10), cujas partes laterais se elevam e se afastam da linha média, aumentando o diâmetro transverso. As flutuantes (11-12) têm pouco papel mecânico direto na expansão volumétrica.","option_rationales":{"a":"Errada. As costelas superiores fazem movimento de \"braço de bomba\".","b":"Errada. Costelas 3-6 aumentam principalmente o diâmetro anteroposterior.","c":"Correta. 7ª a 10ª realizam o movimento de alça de balde.","d":"Errada. 11ª e 12ª são flutuantes e não fixas ao esterno.","e":"Errada. As flutuantes não contribuem para o movimento de alça de balde eficiente."},"difficulty":"Difícil","tags":["Anatomia","Tórax","Biomecânica"]}', '3a80719a758087c8edd98a50406c3714', 11, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Um paciente submetido a uma nefrectomia radical por via lombar (incisão de lombo-laparotomia) apresenta, no pós-operatório, uma fraqueza na musculatura abdominal anterolateral e perda de sensibilidade na região suprapúbica. O cirurgião suspeita de lesão nervosa durante a incisão muscular profunda. Qual nervo, que percorre a face anterior do músculo quadrado lombar e perfura o músculo transverso do abdome, é o mais provável de ter sido lesado?","options":{"a":"Nervo femoral.","b":"Nervo ilio-hipogástrico.","c":"Nervo obturador.","d":"Nervo genitofemoral.","e":"Nervo subcostal."},"answer":"b","rationale":"O nervo ilio-hipogástrico (L1) emerge da borda lateral do psoas maior, passa anteriormente ao quadrado lombar e perfura o transverso do abdome próximo à crista ilíaca. Ele supre os músculos da parede abdominal e fornece sensibilidade à pele da região glútea lateral e suprapúbica. Sua localização o torna vulnerável em incisões lombares ou renais.","option_rationales":{"a":"Errada. O nervo femoral é profundo e emerge entre o psoas e o ilíaco, dirigindo-se à coxa.","b":"Correta. Sua topografia condiz com o risco em cirurgias renais via lombar.","c":"Errada. O nervo obturador corre medialmente ao psoas para o forame obturado.","d":"Errada. O genitofemoral perfura o músculo psoas na sua face anterior.","e":"Errada. O subcostal (T12) corre logo abaixo da 12ª costela; embora vulnerável, o relato de parestesia suprapúbica aponta mais para L1."},"difficulty":"Difícil","tags":["Anatomia","Plexo Lombar","Parede Abdominal"]}', '6439406d36811e57cfc8762f59197ce0', 12, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O canal vertebral contém a medula espinal, as meninges e as raízes nervosas. Em um adulto jovem saudável, em qual nível vertebral a medula espinal geralmente termina, dando início à cauda equina?","options":{"a":"L1 - L2.","b":"L4 - L5.","c":"S1 - S2.","d":"T10 - T11.","e":"No nível do cóccix."},"answer":"a","rationale":"No feto, a medula ocupa toda a extensão do canal vertebral. Devido ao crescimento diferencial da coluna vertebral e do tecido nervoso (ascensão aparente da medula), no adulto, o cone medular (final da medula espinal) situa-se geralmente no nível do disco intervertebral entre L1 e L2. Por isso, punções lombares são realizadas com segurança abaixo deste nível (ex: L3-L4 ou L4-L5).","option_rationales":{"a":"Correta. Nível fisiológico padrão no adulto.","b":"Errada. Nível comum para punção lombar, já no espaço da cauda equina.","c":"Errada. S1-S2 é o nível onde termina o saco dural, não a medula.","d":"Errada. Nível muito elevado; a medula continua abaixo de T12.","e":"Errada. Incorreto; a medula termina muito antes do cóccix no adulto."},"difficulty":"Fácil","tags":["Anatomia","Medula Espinal","Neuroanatomia"]}', '60e7102d6abbd78f91e8bfe5cb6c9d78', 13, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As costelas são classificadas como verdadeiras, falsas ou flutuantes baseadas em sua fixação ao esterno. Um paciente com dor torácica localizada na junção das cartilagens costais com o esterno (condrite) é avaliado. Anatômica e sistematicamente, quais são as costelas consideradas \"verdadeiras\" (vertebrocostais)?","options":{"a":"1ª a 5ª costelas.","b":"1ª a 7ª costelas.","c":"1ª a 10ª costelas.","d":"8ª a 10ª costelas.","e":"11ª e 12ª costelas."},"answer":"b","rationale":"Costelas verdadeiras (1ª-7ª) são aquelas cujas cartilagens costais se articulam diretamente com o esterno. As falsas (8ª-10ª) têm suas cartilagens unidas à cartilagem da costela imediatamente superior, formando a margem costal. As flutuantes (11ª-12ª) não possuem fixação anterior, terminando na musculatura abdominal posterior.","option_rationales":{"a":"Errada. Incompleto, a 6ª e 7ª também são verdadeiras.","b":"Correta. Classificação clássica das costelas vertebrocostais.","c":"Errada. Inclui as costelas falsas (8-10).","d":"Errada. Estas são as costelas falsas.","e":"Errada. Estas são as costelas flutuantes."},"difficulty":"Fácil","tags":["Anatomia","Tórax","Osteologia"]}', 'ac4a0e48397be0e361657ff4009f09d2', 14, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo grande dorsal (latissimus dorsi) é um dos maiores e mais superficiais músculos do dorso. Ele possui uma origem extensa e se insere no úmero. Sabendo que este músculo é clinicamente testado pedindo ao paciente para aduzir o braço contra resistência (movimento de \"coçar as costas\"), identifique o nervo responsável por sua inervação.","options":{"a":"Nervo acessório (XI par).","b":"Nervo dorsal da escápula.","c":"Nervo toracodorsal.","d":"Nervo torácico longo.","e":"Nervos intercostais."},"answer":"c","rationale":"O músculo grande dorsal é inervado pelo nervo toracodorsal (ramo do fascículo posterior do plexo braquial, raízes C6, C7, C8). Lesões desse nervo (por exemplo, em cirurgias de esvaziamento axilar por câncer de mama) resultam em fraqueza na extensão, adução e rotação medial do úmero.","option_rationales":{"a":"Errada. O nervo acessório inerva o trapézio e o esternocleidomastoideo.","b":"Errada. O dorsal da escápula inerva os romboides e o levantador da escápula.","c":"Correta. Nervo específico para o músculo grande dorsal.","d":"Errada. O torácico longo inerva o músculo serrátil anterior.","e":"Errada. O grande dorsal é um músculo extrínseco do dorso derivado do membro superior, não sendo inervado por ramos segmentares do tronco."},"difficulty":"Média","tags":["Anatomia","Músculos","Plexo Braquial"]}', '3ea75ab564c09e0135b3802c2c541d79', 15, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A herniação de disco intervertebral ocorre mais frequentemente em direção posterolateral devido a uma característica anatômica específica dos ligamentos da coluna vertebral. Qual ligamento reforça a face anterior dos corpos vertebrais e discos, mas torna-se estreito e menos resistente na sua porção posterior?","options":{"a":"Ligamento longitudinal anterior.","b":"Ligamento longitudinal posterior.","c":"Ligamento amarelo.","d":"Ligamento nucal.","e":"Ligamento supraespinal."},"answer":"b","rationale":"O ligamento longitudinal anterior é largo e forte, cobrindo a face anterior dos corpos vertebrais. Já o ligamento longitudinal posterior percorre o interior do canal vertebral; ele é mais estreito e fraco, especialmente nas margens posterolaterais dos discos intervertebrais. Essa \"fraqueza\" anatômica lateral ao ligamento posterior é o caminho de menor resistência para o núcleo pulposo herniar.","option_rationales":{"a":"Errada. O longitudinal anterior é extremamente forte e largo.","b":"Correta. Sua conformação estreita predispõe a hérnias posterolaterais.","c":"Errada. O ligamento amarelo está no arco vertebral, não no corpo.","d":"Errada. Ligamento cervical posterior.","e":"Errada. Conecta os processos espinhosos."},"difficulty":"Média","tags":["Anatomia","Coluna Vertebral","Patologia Anatômica"]}', 'cec636be8cf52bb2e9a776dc035ad3e1', 16, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Uma criança de 4 anos aspira acidentalmente um pequeno brinquedo de plástico. O exame radiográfico sugere que o corpo estranho está alojado em um dos brônquios principais. De acordo com a anatomia da árvore brônquica, em qual brônquio o objeto tem maior probabilidade de ser encontrado?","options":{"a":"Brônquio principal esquerdo, por ser mais horizontal e largo.","b":"Brônquio principal direito, por ser mais vertical, mais curto e mais largo.","c":"Brônquio principal esquerdo, por ser mais longo e estreito.","d":"Brônquio principal direito, por ser mais longo e horizontal.","e":"Ambos têm a mesma probabilidade anatômica."},"answer":"b","rationale":"O brônquio principal direito é mais vertical (forma ângulo menos agudo com a traqueia), mais curto (aproximadamente 2,5 cm) e mais largo que o esquerdo. Essas características anatômicas facilitam a passagem de corpos estranhos aspirados, que tendem a seguir a trajetória retilínea da traqueia para o pulmão direito.","option_rationales":{"a":"Errada. O esquerdo é mais horizontal, o que dificulta o alojamento de objetos.","b":"Correta. Morfologia clássica que explica a epidemiologia da aspiração.","c":"Errada. Características corretas do esquerdo, mas que diminuem a chance de aspiração.","d":"Errada. O direito é curto e vertical.","e":"Errada. Há uma clara predisposição anatômica para o lado direito."},"difficulty":"Fácil","tags":["Anatomia","Sistema Respiratório","Clínica."]}', '0c7e624b3565434d3d79aaa1a55de131', 17, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As articulações sinoviais dos processos articulares da coluna vertebral, que permitem movimentos de deslizamento entre vértebras adjacentes, são conhecidas como:","options":{"a":"Sinfises intervertebrais.","b":"Articulações uncovertebrais (de Luschka).","c":"Articulações zigapofisárias.","d":"Sindesmoses interlaminares.","e":"Esquindileses cervicais."},"answer":"c","rationale":"As articulações zigapofisárias (ou articulações de facetas) são articulações sinoviais planas entre os processos articulares superior de uma vértebra e inferior da vértebra sobrejacente. Elas determinam o tipo de movimento permitido em cada região da coluna (ex: rotação na torácica, flexão/extensão na lombar). Degenerações nessas articulações são causas comuns de dor nas costas crônica.","option_rationales":{"a":"Errada. Sinfises referem-se aos discos entre os corpos vertebrais (cartilaginosas).","b":"Errada. Estas ocorrem apenas na região cervical entre os processos uncinados.","c":"Correta. Nomenclatura anatômica padrão para as facetas articulares.","d":"Errada. Sindesmoses interlaminares referem-se à união pelos ligamentos amarelos.","e":"Errada. Esquindilese é um tipo de articulação fibrosa rara (ex: vômer com esfenoide)."},"difficulty":"Média","tags":["Anatomia","Artrologia","Coluna Vertebral"]}', '9be3906e45f1937c183d0d510123ff1f', 18, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo psoas maior é um músculo volumoso que compõe a parede abdominal posterior. Ele tem origem nos processos transversos e corpos das vértebras lombares (T12-L5). Sabendo que seu tendão se une ao músculo ilíaco para se inserir no fêmur, identifique o seu local de inserção distal e a sua função principal no quadril.","options":{"a":"Trocânter maior; Extensão do quadril.","b":"Trocânter menor; Flexão do quadril.","c":"Linha áspera; Adução do quadril.","d":"Epicôndilo medial; Rotação externa do joelho.","e":"Tuberosidade isquiática; Estabilização da pélvis."},"answer":"b","rationale":"O músculo iliopsoas (fusão do psoas maior e ilíaco) é o flexor mais potente do quadril. Ele se insere distalmente no trocânter menor do fêmur. Além da flexão do quadril, ele atua na flexão do tronco e na estabilização da postura ereta. É um músculo clinicamente importante, pois abscessos de coluna (ex: mal de Pott) podem drenar através de sua fáscia até a coxa.","option_rationales":{"a":"Errada. O trocânter maior é local de inserção de glúteos e rotadores externos; o psoas não estende o quadril.","b":"Correta. Inserção no trocânter menor e função de flexão.","c":"Errada. Músculos adutores inserem-se na linha áspera.","d":"Errada. Foge totalmente da anatomia do psoas.","e":"Errada. A tuberosidade isquiática é origem dos hamstrings (isquiotibiais)."},"difficulty":"Fácil","tags":["Anatomia","Músculos","Membro Inferior"]}', 'dff5804a0707541d7341abfe7aa65f36', 19, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A clavícula é o primeiro osso a ossificar e o único osso longo que se ossifica em membrana. Em caso de fratura, a maioria ocorre no terço médio, devido à sua curvatura. Qual músculo, ao tracionar o fragmento medial superiormente após uma fratura, é responsável pelo desvio característico visível no exame físico?","options":{"a":"Deltoide.","b":"Peitoral maior.","c":"Esternocleidomastoideo.","d":"Trapézio.","e":"Subclávio."},"answer":"c","rationale":"Na fratura de clavícula, o músculo esternocleidomastoideo traciona o fragmento medial para cima, enquanto o peso do braço e a ação do peitoral maior puxam o fragmento lateral para baixo e medialmente. O subclávio, por sua vez, pode proteger os vasos subclávios subjacentes em caso de fraturas não cominutivas.","option_rationales":{"a":"Errada. O deltoide traciona o fragmento lateral.","b":"Errada. O peitoral maior traciona o fragmento lateral medialmente.","c":"Correta. Tração superior do fragmento medial.","d":"Errada. O trapézio atua na estabilização posterior da escápula.","e":"Errada. O subclávio atua puxando a clavícula inferiormente, não o fragmento medial superiormente."},"difficulty":"Fácil","tags":["Anatomia","Osteologia","Membro Superior"]}', 'e612e116c663c142be479e6b8ea8c216', 20, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo iliopsoas é o principal flexor do quadril. Ele é formado pela união dos músculos psoas maior e ilíaco. O psoas menor, quando presente, situa-se anteriormente ao psoas maior. Qual é o local de inserção distal comum do tendão do músculo iliopsoas no fêmur?","options":{"a":"Trocânter maior.","b":"Trocânter menor.","c":"Linha pectínea.","d":"Crista intertrocantérica.","e":"Fossa trocantérica."},"answer":"b","rationale":"O tendão do iliopsoas insere-se no trocânter menor do fêmur. É o mais potente flexor da articulação do quadril, essencial para a marcha e para levantar-se da posição sentada.","option_rationales":{"a":"Errada. Inserção de glúteos e piriforme.","b":"Correta. Localização clássica de inserção do iliopsoas.","c":"Errada. Local de inserção do músculo pectíneo.","d":"Errada. Marco ósseo posterior do fêmur.","e":"Errada. Local de inserção do músculo obturador externo."},"difficulty":"Fácil","tags":["Anatomia","Miologia","Membro Inferior"]}', '5214cd8573e610beaa9530f83407ba8f', 21, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A anatomia do pescoço é organizada em triângulos delimitados por músculos proeminentes. O triângulo carótico, local de palpação do pulso carotídeo, é delimitado por quais músculos?","options":{"a":"Esternocleidomastoideo, ventre superior do omo-hioideo e ventre posterior do digástrico.","b":"Trapézio, clavícula e esternocleidomastoideo.","c":"Mandíbula, ventre anterior e posterior do digástrico.","d":"Esternocleidomastoideo, esterno-hioideo e mandíbula.","e":"Escaleno anterior, escaleno médio e 1ª costela."},"answer":"a","rationale":"O triângulo carótico é delimitado pelo bordo anterior do músculo esternocleidomastoideo, pelo ventre posterior do músculo digástrico e pelo ventre superior do músculo omo-hioideo. Contém a artéria carótida comum e sua bifurcação.","option_rationales":{"a":"Correta. Limites clássicos do triângulo carótico.","b":"Errada. Limites do triângulo cervical posterior.","c":"Errada. Limites do triângulo submandibular.","d":"Errada. Descrição incorreta de triângulos cervicais.","e":"Errada. Limites do espaço interescalênico."},"difficulty":"Média","tags":["Anatomia","Miologia","Pescoço"]}', 'a7b48fc64e4949f3c931cb9f4c3ef606', 22, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Dentre os ossos do tarso, qual é o único que não possui inserções musculares ou tendinosas diretas, transmitindo todo o peso do corpo da tíbia para o calcâneo e o restante do pé?","options":{"a":"Calcâneo.","b":"Talus (astrágalo).","c":"Navicular.","d":"Cuboide.","e":"Cuneiforme medial."},"answer":"b","rationale":"O talus é o osso do tarso que se articula com a tíbia e a fíbula na articulação do tornozelo. Ele é recoberto por cartilagem articular em grande parte de sua superfície e é único por não possuir nenhuma inserção muscular ou tendinosa em suas faces.","option_rationales":{"a":"Errada. O calcâneo recebe a inserção do tendão calcâneo (Aquiles).","b":"Correta. O talus não possui inserções musculares diretas.","c":"Errada. O tibial posterior insere-se no navicular.","d":"Errada. O tibial posterior também tem expansões para o cuboide.","e":"Errada. O tibial anterior e o tibial posterior inserem-se nos cuneiformes."},"difficulty":"Média","tags":["Anatomia","Osteologia","Membro Inferior"]}', '2e9ced17390ba2d2c558862306908dce', 23, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O músculo diafragma possui três grandes aberturas (hiatos) que permitem a passagem de estruturas fundamentais entre essas cavidades. O forame da veia cava localiza-se em qual porção do diafragma e em qual nível vertebral?","options":{"a":"Centro tendíneo Nível T8.","b":"Parte muscular vertebral; Nível T10.","c":"Pilar direito; Nível T12.","d":"Ligamento arqueado mediano; Nível L1.","e":"Trígono lombo-costal; Nível T12."},"answer":"a","rationale":"O forame da veia cava situa-se no centro tendíneo do diafragma, geralmente no nível da 8ª vértebra torácica (T8). Além da veia cava inferior, ramos do nervo frênico direito também atravessam essa abertura.","option_rationales":{"a":"Correta. Localização e nível vertebral do forame da veia cava.","b":"Errada. Nível T10 corresponde ao hiato esofágico.","c":"Errada. Nível T12 corresponde ao hiato aórtico.","d":"Errada. O ligamento arqueado mediano forma o hiato aórtico.","e":"Errada. O trígono lombo-costal é uma zona de fraqueza, não um hiato anatômico para grandes vasos."},"difficulty":"Fácil","tags":["Anatomia","Miologia","Diafragma"]}', '74282a3929e5b22c02cfcc5f777116e3', 24, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A parede abdominal anterior é formada por vários músculos e suas aponeuroses. Abaixo da linha arqueada (de Douglas), a bainha do músculo reto abdominal apresenta qual configuração anatômica em relação às lâminas aponeuróticas?","options":{"a":"Todas as aponeuroses passam posteriormente ao músculo reto.","b":"A aponeurose do oblíquo interno se divide, uma parte passando anterior e outra posterior ao reto.","c":"Todas as aponeuroses passam anteriormente ao músculo reto, deixando-o em contato direto com a fáscia transversalis posteriormente.","d":"A bainha é ausente abaixo da linha arqueada, sendo o músculo coberto apenas por pele.","e":"A aponeurose do transverso do abdome permanece posterior ao músculo reto."},"answer":"c","rationale":"Acima da linha arqueada, as aponeuroses se distribuem anterior e posteriormente ao reto. Porém, abaixo da linha arqueada (cerca de 5 cm abaixo da cicatriz umbilical), as aponeuroses do oblíquo externo, oblíquo interno e transverso do abdome passam todas ANTERIORMENTE ao músculo reto, formando a lâmina anterior da bainha. Posteriormente, o músculo reto fica em contato apenas com a fáscia transversalis e o peritônio.","option_rationales":{"a":"Errada. Isso não ocorre em nenhum nível.","b":"Errada. Isso ocorre APENAS acima da linha arqueada.","c":"Correta. Descrição clássica da transição na linha arqueada.","d":"Errada. O músculo sempre é protegido internamente por fáscia e peritônio.","e":"Errada. Abaixo da linha arqueada, ela passa para a frente."},"difficulty":"Difícil","tags":["Anatomia","Parede Abdominal","Miologia"]}', 'a6270b88c780a159f36c4182fe9f9a40', 25, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A fáscia toracolombar é uma estrutura aponeurótica complexa no dorso. Ela é composta por várias camadas. Qual desses músculos tem sua origem diretamente relacionada à camada posterior da fáscia toracolombar?","options":{"a":"Latíssimo do dorso (grande dorsal).","b":"Trapézio.","c":"Eretor da espinha.","d":"Multífido.","e":"Quadrado lombar."},"answer":"a","rationale":"O músculo latíssimo do dorso tem uma origem aponeurótica extensa na fáscia toracolombar (camada posterior), além dos processos espinhosos de T7-L5 e crista ilíaca.","option_rationales":{"a":"Correta. Origem principal do grande dorsal no dorso inferior.","b":"Errada. O trapézio origina-se na linha nucal e processos espinhosos cervicais/torácicos superiores.","c":"Errada. O eretor da espinha situa-se ENTRE as camadas da fáscia, mas não origina a camada posterior.","d":"Errada. O multífido é profundo e situa-se medialmente ao eretor.","e":"Errada. O quadrado lombar situa-se entre as camadas média e anterior da fáscia toracolombar."},"difficulty":"Média","tags":["Anatomia","Miologia","Dorso"]}', '0eb5b56371ee66de5431e608408621ab', 26, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O plexo coccígeo é formado por pequenos ramos nervosos. No entanto, o nervo frênico, essencial para a respiração, tem sua origem principal em qual plexo e quais raízes?","options":{"a":"Plexo braquial; C5-C7.","b":"Plexo cervical; C3-C5.","c":"Plexo lombar; L1-L3.","d":"Plexo sacral; S2-S4.","e":"Plexo celíaco; Nervos esplâncnicos."},"answer":"b","rationale":"O nervo frênico origina-se primordialmente do 4º nervo cervical (C4), com contribuições de C3 e C5 (mnemônico: \"C3, 4, 5 keep the diaphragm alive\"). Ele atravessa o pescoço e o tórax para inervar o diafragma.","option_rationales":{"a":"Errada. C5 pode contribuir, mas a origem é cervical superior.","b":"Correta. Origem clássica do nervo frênico.","c":"Errada. O plexo lombar supre membros inferiores e parede abdominal.","d":"Errada. O plexo sacral supre períneo e membros inferiores.","e":"Errada. O plexo celíaco é autonômico (simpático/parassimpático)."},"difficulty":"Fácil","tags":["Anatomia","Neuroanatomia","Sistema Respiratório"]}', 'c3007916cfa7506aec07d3f3de0bb56d', 27, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O canal do carpo é uma passagem estreita no punho por onde transitam tendões e o nervo mediano. Qual estrutura anatômica forma o teto (limite superficial) desse canal e cuja secção cirúrgica é o tratamento definitivo para a síndrome do túnel do carpo?","options":{"a":"Retináculo dos flexores (ligamento carpal transverso).","b":"Aponeurose palmar.","c":"Retináculo dos extensores.","d":"Ligamento colateral ulnar.","e":"Tendão do palmar longo."},"answer":"a","rationale":"O retináculo dos flexores é uma banda fibrosa resistente que se estende entre o escafoide/trapézio e o pisiforme/hamato. Ele forma o teto do túnel do carpo, mantendo os tendões flexores em posição. Seu espessamento pode comprimir o nervo mediano.","option_rationales":{"a":"Correta. Estrutura alvo na síndrome do túnel do carpo.","b":"Errada. A aponeurose palmar é superficial ao retináculo na palma da mão.","c":"Errada. O retináculo dos extensores localiza-se na face dorsal do punho.","d":"Errada. Estabiliza o lado medial da articulação do punho.","e":"Errada. O tendão do palmar longo passa SUPERFICIALMENTE ao retináculo e não compõe o teto do canal."},"difficulty":"Média","tags":["Anatomia","Membro Superior","Aplicação Clínica"]}', '3cec99ac228f6204cb177e9f02000923', 28, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Os músculos intercostais são fundamentais para a mecânica respiratória. Sobre a disposição de suas fibras, assinale a alternativa que descreve corretamente a orientação das fibras do músculo intercostal externo.","options":{"a":"De cima para baixo e de trás para frente (sentido das mãos no bolso).","b":"De cima para baixo e de frente para trás.","c":"Horizontalmente entre as costelas.","d":"Verticalmente unindo as bordas das costelas.","e":"Em sentido perpendicular às fibras do intercostal íntimo."},"answer":"a","rationale":"Os músculos intercostais externos têm suas fibras orientadas obliquamente, de cima para baixo e de trás para frente (anteroinferiormente). Essa orientação é análoga à dos músculos oblíquos externos do abdome e auxilia na elevação das costelas durante a inspiração.","option_rationales":{"a":"Correta. Orientação clássica \"mãos no bolso\".","b":"Errada. Esta seria a orientação inversa (intercostais internos).","c":"Errada. Nenhuma camada intercostal é puramente horizontal.","d":"Errada. Disposição incorreta.","e":"Errada. As fibras do intercostal íntimo têm a mesma direção que as do interno, sendo perpendiculares às do externo."},"difficulty":"Média","tags":["Anatomia","Miologia","Tórax"]}', 'd00ba6d070122cc6e6c918bfd75d2eeb', 29, 'draft');;